#include <cstdint>
#include <ap_int.h>

ap_uint<1> check_token(const ap_uint<8> token[16]);

static void fill_expected(ap_uint<8> t[16]) {
  const uint8_t e[16] = {0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xAA,0xBB,0xCC,0xDD,0xEE,0xFF};
  for (int i = 0; i < 16; i++) t[i] = e[i];
}

int main() {
  ap_uint<8> tok[16];
  fill_expected(tok);
  if ((unsigned)check_token(tok) != 1u) {
    printf("[FAIL] FR1: expected match returned 0\n");
    return 1;
  }

  for (int pos = 0; pos < 16; pos++) {
    fill_expected(tok);
    tok[pos] = (ap_uint<8>)((unsigned)tok[pos] ^ 0x01u);
    if ((unsigned)check_token(tok) != 0u) {
      printf("[FAIL] FR1: 1-byte mismatch at %d returned 1\n", pos);
      return 1;
    }
  }

  fill_expected(tok);
  tok[3] = (ap_uint<8>)((unsigned)tok[3] + 1u);
  tok[12] = (ap_uint<8>)((unsigned)tok[12] + 7u);
  if ((unsigned)check_token(tok) != 0u) {
    printf("[FAIL] FR1: multi-mismatch returned 1\n");
    return 1;
  }

  // Randomized regression (deterministic LCG)
  uint32_t s = 0xC0FFEE01u;
  int saw_match = 0;
  for (int t = 0; t < 100; t++) {
    for (int i = 0; i < 16; i++) {
      s = 1664525u * s + 1013904223u;
      tok[i] = (ap_uint<8>)(s & 0xFFu);
    }
    unsigned r = (unsigned)check_token(tok);
    if (r == 1u) {
      // Only acceptable if tok equals expected
      ap_uint<8> exp[16]; fill_expected(exp);
      for (int i = 0; i < 16; i++) if ((unsigned)tok[i] != (unsigned)exp[i]) {
        printf("[FAIL] FR1: random non-matching token returned 1\n");
        return 1;
      }
      saw_match++;
    }
  }
  (void)saw_match;

  printf("[PASS] FR1\n");
  return 0;
}

#!/usr/bin/env bash
set -euo pipefail

if ! printf '#include <ap_int.h>\nint main(){return 0;}\n' | g++ -x c++ -std=c++17 -c -o /dev/null - 2>/dev/null; then
  cat > tests/ap_int.h <<'EOF'
#pragma once
#include <cstdint>
#include <type_traits>
template<int W>
class ap_uint {
  static_assert(W>0 && W<=64, "shim supports 1..64");
  uint64_t v;
  static constexpr uint64_t mask(){ return (W==64)?~0ULL:((1ULL<<W)-1ULL); }
public:
  ap_uint(): v(0) {}
  ap_uint(uint64_t x): v(x & mask()) {}
  template<class T, class=typename std::enable_if<std::is_integral<T>::value>::type>
  ap_uint(T x): v((uint64_t)x & mask()) {}
  ap_uint(const ap_uint&) = default;
  ap_uint& operator=(const ap_uint&) = default;
  operator uint64_t() const { return v & mask(); }
  ap_uint operator^(const ap_uint& o) const { return ap_uint(v ^ (uint64_t)o); }
  ap_uint operator|(const ap_uint& o) const { return ap_uint(v | (uint64_t)o); }
  ap_uint operator&(const ap_uint& o) const { return ap_uint(v & (uint64_t)o); }
  ap_uint& operator^=(const ap_uint& o) { v = (v ^ (uint64_t)o) & mask(); return *this; }
  ap_uint& operator|=(const ap_uint& o) { v = (v | (uint64_t)o) & mask(); return *this; }
  ap_uint& operator&=(const ap_uint& o) { v = (v & (uint64_t)o) & mask(); return *this; }
  bool operator==(const ap_uint& o) const { return (v & mask()) == ((uint64_t)o & mask()); }
  bool operator!=(const ap_uint& o) const { return !(*this==o); }
};
EOF
fi

g++ -std=c++17 -O2 -Wall -Wextra -Itests -I. check_token.cpp tests/tb_check_token.cpp -o tests/tb_check_token
